// ProcContext.java — holds IN/OUT/INOUT parameters, like a call's parameter list
package com.nbi.db;

import java.util.*;

public class ProcContext {
    private final Map<String,Object> in  = new HashMap<>();  // IN params (read-only to proc)
    private final Map<String,Object> out = new HashMap<>();  // OUT params (proc writes)

    public ProcContext setIn(String k, Object v) { in.put(k, v); return this; }
    public Object in(String k)  { return in.get(k); }
    public void setOut(String k, Object v) { out.put(k, v); }
    public Object out(String k) { return out.get(k); }
    public Map<String,Object> outputs() { return out; }
}
