// TransferFundsProc.java — CREATE PROCEDURE transfer_funds(IN ..., OUT ...)
package com.nbi.db;

import java.util.Map;

public class TransferFundsProc {
    private final Map<String,Double> balances; // stands in for the accounts table

    public TransferFundsProc(Map<String,Double> balances) { this.balances = balances; }

    // Equivalent SQL signature:
    //   CREATE PROCEDURE transfer_funds(
    //       IN  p_from   VARCHAR, IN p_to VARCHAR, IN p_amount NUMERIC,
    //       OUT p_status VARCHAR, OUT p_new_from_balance NUMERIC)
    public void call(ProcContext ctx) {
        String from   = (String) ctx.in("p_from");      // IN
        String to     = (String) ctx.in("p_to");        // IN
        double amount = (double) ctx.in("p_amount");    // IN

        // --- encapsulated, atomic business logic (runs in the DB) ---
        Double src = balances.get(from);
        if (src == null || balances.get(to) == null) {
            ctx.setOut("p_status", "FAILED_UNKNOWN_ACCOUNT");   // OUT status
            ctx.setOut("p_new_from_balance", src);              // OUT value
            return;
        }
        if (src < amount) {
            ctx.setOut("p_status", "FAILED_INSUFFICIENT_FUNDS");
            ctx.setOut("p_new_from_balance", src);
            return;
        }
        balances.put(from, src - amount);                  // debit source
        balances.put(to, balances.get(to) + amount);       // credit target
        ctx.setOut("p_status", "SUCCESS");                 // OUT status
        ctx.setOut("p_new_from_balance", balances.get(from)); // OUT new balance
    }
}
