// Demo.java — CALL transfer_funds with IN args, read OUT params
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        Map<String,Double> balances = new HashMap<>(Map.of("A100", 50000.0, "A200", 2000.0));
        TransferFundsProc proc = new TransferFundsProc(balances);

        // CALL transfer_funds('A100','A200', 15000, @status, @bal);
        ProcContext ok = new ProcContext()
            .setIn("p_from","A100").setIn("p_to","A200").setIn("p_amount",15000.0);
        proc.call(ok);
        System.out.println("Call 1: " + ok.outputs()); // OUT params returned

        // A failing call: insufficient funds
        ProcContext fail = new ProcContext()
            .setIn("p_from","A200").setIn("p_to","A100").setIn("p_amount",999999.0);
        proc.call(fail);
        System.out.println("Call 2: " + fail.outputs());

        System.out.println("Final balances: " + balances);
    }
}
